import crypto from 'crypto';

import { EmploymentStatus } from '../../shared/types/index';
import { Employee } from './employee.model';
import { IEmployeeRepository } from './employee.repository.interface';
import { CreateEmployeeDto, IEmployeeService } from './employee.service.interface';

export class EmployeeService implements IEmployeeService {
  constructor(private readonly repo: IEmployeeRepository) {}

  async getById(id: string): Promise<Employee | null> {
    return this.repo.findById(id);
  }

  async getByEmployeeNumber(employeeNumber: string): Promise<Employee | null> {
    return this.repo.findByEmployeeNumber(employeeNumber);
  }

  async getSubordinates(managerId: string): Promise<Employee[]> {
    return this.repo.findByManagerId(managerId);
  }

  async create(data: CreateEmployeeDto): Promise<Employee> {
    const now = new Date();
    const employee: Employee = {
      id: crypto.randomUUID(),
      employeeNumber: data.employeeNumber,
      firstName: data.firstName,
      lastName: data.lastName,
      email: data.email,
      managerId: data.managerId ?? null,
      department: data.department,
      hireDate: data.hireDate,
      terminationDate: null,
      employmentStatus: EmploymentStatus.ACTIVE,
      createdAt: now,
      updatedAt: now,
      deletedAt: null,
    };
    return this.repo.create(employee);
  }

  async update(id: string, data: Partial<Employee>): Promise<Employee | null> {
    const allowedFields: (keyof Employee)[] = [
      'firstName',
      'lastName',
      'email',
      'managerId',
      'department',
      'hireDate',
    ];
    const sanitized: Partial<Employee> = {};
    for (const key of allowedFields) {
      if (key in data) {
        (sanitized as Record<string, unknown>)[key] = (data as Record<string, unknown>)[key];
      }
    }
    return this.repo.update(id, sanitized);
  }

  async terminate(id: string): Promise<Employee | null> {
    const existing = await this.repo.findById(id);
    if (!existing) {
      return null;
    }
    return this.repo.update(id, {
      employmentStatus: EmploymentStatus.TERMINATED,
      terminationDate: new Date(),
    });
  }
}
import { FastifyReply, FastifyRequest } from 'fastify';

import { IEmployeeService } from './employee.service.interface';

export function makeEmployeeController(service: IEmployeeService) {
  return {
    getEmployeeById: async (request: FastifyRequest, reply: FastifyReply) => {
      const { id } = request.params as { id: string };
      const employee = await service.getById(id);
      if (!employee) {
        return reply.status(404).send({ error: 'Employee not found' });
      }
      return reply.status(200).send(employee);
    },

    getEmployeeByNumber: async (request: FastifyRequest, reply: FastifyReply) => {
      const { employeeNumber } = request.params as { employeeNumber: string };
      const employee = await service.getByEmployeeNumber(employeeNumber);
      if (!employee) {
        return reply.status(404).send({ error: 'Employee not found' });
      }
      return reply.status(200).send(employee);
    },

    getSubordinates: async (request: FastifyRequest, reply: FastifyReply) => {
      const { managerId } = request.params as { managerId: string };
      const subordinates = await service.getSubordinates(managerId);
      return reply.status(200).send(subordinates);
    },

    createEmployee: async (request: FastifyRequest, reply: FastifyReply) => {
      const data = request.body as Record<string, unknown>;
      const employee = await service.create({
        employeeNumber: data.employeeNumber as string,
        firstName: data.firstName as string,
        lastName: data.lastName as string,
        email: data.email as string,
        managerId: data.managerId as string | null | undefined,
        department: data.department as string,
        hireDate: new Date(data.hireDate as string),
      });
      return reply.status(201).send(employee);
    },

    updateEmployee: async (request: FastifyRequest, reply: FastifyReply) => {
      const { id } = request.params as { id: string };
      const data = request.body as Record<string, unknown>;
      const employee = await service.update(id, data);
      if (!employee) {
        return reply.status(404).send({ error: 'Employee not found' });
      }
      return reply.status(200).send(employee);
    },

    terminateEmployee: async (request: FastifyRequest, reply: FastifyReply) => {
      const { id } = request.params as { id: string };
      const employee = await service.terminate(id);
      if (!employee) {
        return reply.status(404).send({ error: 'Employee not found' });
      }
      return reply.status(200).send(employee);
    },
  };
}
import { FastifyInstance } from 'fastify';

import { makeEmployeeController } from './employee.controller';
import { EmployeeService } from './employee.service';
import { IEmployeeRepository } from './employee.repository.interface';

export async function employeeRoutes(
  fastify: FastifyInstance,
  repo: IEmployeeRepository,
): Promise<void> {
  const service = new EmployeeService(repo);
  const controller = makeEmployeeController(service);

  fastify.get('/employees/:id', controller.getEmployeeById);
  fastify.get('/employees/number/:employeeNumber', controller.getEmployeeByNumber);
  fastify.get('/employees/:managerId/subordinates', controller.getSubordinates);
  fastify.post('/employees', controller.createEmployee);
  fastify.put('/employees/:id', controller.updateEmployee);
  fastify.post('/employees/:id/terminate', controller.terminateEmployee);
}
